-- requirement_doc（47 行）
INSERT INTO requirement_doc (id, workspace_id, req_id, parent_id, title, content, format, content_brief, status, sort_order, owner, owner_user_id, created_at, updated_at) VALUES
  ('XmD0111', 'SXm01', 'XmR011', 'XmD0110', 'V1.0 需求说明', '<h2>背景与目标</h2><p>首版：微信/支付宝收单、统一下单与回调。</p><h2>需求范围</h2><ul><li><strong>统一下单接口</strong>：屏蔽渠道差异的统一下单 API，支持幂等单号</li><li><strong>微信支付渠道接入</strong>：JSAPI / Native 两种模式与签名验签</li><li><strong>支付宝渠道接入</strong>：当面付与手机网站支付</li><li><strong>收银台 H5 页面</strong>：多渠道选择、倒计时与结果页</li></ul><h2>验收标准</h2><ol><li>统一下单接口功能完整可用，异常场景有明确提示</li><li>微信支付渠道接入功能完整可用，异常场景有明确提示</li><li>支付宝渠道接入功能完整可用，异常场景有明确提示</li><li>收银台 H5 页面功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-06-30 发布，发布前完成回归测试与上线评审。</p>', 'html', '首版：微信/支付宝收单、统一下单与回调。范围：统一下单接口、微信支付渠道接入、支付宝渠道接入、收银台 H5 页面', 'done', 1, '张伟', 'Xmu01', '2026-04-12 15:00:00', '2026-04-12 15:00:00'),
  ('XmD0112', 'SXm01', 'XmR011', 'XmD0110', 'V1.1 需求说明', '<h2>背景与目标</h2><p>迭代：银联云闪付与退款链路。</p><h2>需求范围</h2><ul><li><strong>银联云闪付接入</strong>：银联全渠道 API 与证书管理</li><li><strong>退款与部分退款</strong>：原路退款、部分退款与退款查询</li><li><strong>商户后台交易查询</strong>：按渠道、状态、时间区间检索交易</li></ul><h2>验收标准</h2><ol><li>银联云闪付接入功能完整可用，异常场景有明确提示</li><li>退款与部分退款功能完整可用，异常场景有明确提示</li><li>商户后台交易查询功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-09-15 发布，发布前完成回归测试与上线评审。</p>', 'html', '迭代：银联云闪付与退款链路。范围：银联云闪付接入、退款与部分退款、商户后台交易查询', 'done', 2, '张伟', 'Xmu01', '2026-06-25 15:00:00', '2026-06-25 15:00:00'),
  ('XmD0113', 'SXm01', 'XmR011', 'XmD0110', 'V1.2 需求说明', '<h2>背景与目标</h2><p>路由与稳定性：智能渠道路由、限流熔断。</p><h2>需求范围</h2><ul><li><strong>智能渠道路由</strong>：按费率、成功率、维护窗口动态选择渠道</li><li><strong>渠道限流与熔断</strong>：单渠道失败率超阈值自动熔断并切换</li><li><strong>路由规则配置页</strong>：可视化配置路由优先级与权重</li></ul><h2>验收标准</h2><ol><li>智能渠道路由功能完整可用，异常场景有明确提示</li><li>渠道限流与熔断功能完整可用，异常场景有明确提示</li><li>路由规则配置页功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-11-20 发布，发布前完成回归测试与上线评审。</p>', 'html', '路由与稳定性：智能渠道路由、限流熔断。范围：智能渠道路由、渠道限流与熔断、路由规则配置页', 'active', 3, '张伟', 'Xmu01', '2026-09-10 15:00:00', '2026-09-10 15:00:00'),
  ('XmD0114', 'SXm01', 'XmR011', 'XmD0110', 'V2.0 需求说明', '<h2>背景与目标</h2><p>跨境支付：多币种收单与外汇结算。</p><h2>需求范围</h2><ul><li><strong>多币种收单</strong>：美元、港币、欧元收单与汇率锁定</li><li><strong>外汇结算对接</strong>：对接持牌机构完成购汇结汇</li><li><strong>多语言收银台</strong>：中英繁三语收银台</li></ul><h2>验收标准</h2><ol><li>多币种收单功能完整可用，异常场景有明确提示</li><li>外汇结算对接功能完整可用，异常场景有明确提示</li><li>多语言收银台功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2027-01-15 发布，发布前完成回归测试与上线评审。</p>', 'html', '跨境支付：多币种收单与外汇结算。范围：多币种收单、外汇结算对接、多语言收银台', 'draft', 4, '张伟', 'Xmu01', '2026-11-15 15:00:00', '2026-11-15 15:00:00'),
  ('XmD0110', 'SXm01', 'XmR011', NULL, '聚合支付网关 产品需求总览', '<h2>项目定位</h2><p>统一接入微信、支付宝、银联等渠道的收单网关。</p><h2>版本规划</h2><ul><li>V1.0（2026-06-30）：首版：微信/支付宝收单、统一下单与回调</li><li>V1.1（2026-09-15）：迭代：银联云闪付与退款链路</li><li>V1.2（2026-11-20）：路由与稳定性：智能渠道路由、限流熔断</li><li>V2.0（2027-01-15）：跨境支付：多币种收单与外汇结算</li></ul><h2>干系人</h2><p>产品负责人：张伟</p>', 'html', '统一接入微信、支付宝、银联等渠道的收单网关。共 4 个版本规划。', 'active', 0, '张伟', 'Xmu01', '2026-04-11 10:00:00', '2026-04-11 10:00:00'),
  ('XmD0119', 'SXm01', 'XmR011', 'XmD0110', '聚合支付网关 接口设计说明', '# 接口设计说明

## 通用约定

- 统一返回 `{ code, message, data }`
- 时间统一使用 `yyyy-MM-dd HH:mm:ss`
- 幂等接口需携带 `Idempotency-Key`

## 错误码

| 错误码 | 含义 |
| --- | --- |
| 0 | 成功 |
| 40001 | 参数错误 |
| 50001 | 系统繁忙 |
', 'markdown', '接口通用约定、返回结构与错误码说明', 'active', 99, '王浩', 'Xmu03', '2026-04-17 16:00:00', '2026-05-10 11:00:00'),
  ('XmD0121', 'SXm01', 'XmR012', 'XmD0120', 'V1.0 需求说明', '<h2>背景与目标</h2><p>首版：渠道账单下载与自动勾兑。</p><h2>需求范围</h2><ul><li><strong>渠道对账单自动下载</strong>：定时拉取微信、支付宝日账单并落库</li><li><strong>交易流水自动勾兑</strong>：按订单号与金额双向勾兑，输出差异</li><li><strong>对账结果看板</strong>：每日勾兑率、差异笔数与金额展示</li></ul><h2>验收标准</h2><ol><li>渠道对账单自动下载功能完整可用，异常场景有明确提示</li><li>交易流水自动勾兑功能完整可用，异常场景有明确提示</li><li>对账结果看板功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-09-10 发布，发布前完成回归测试与上线评审。</p>', 'html', '首版：渠道账单下载与自动勾兑。范围：渠道对账单自动下载、交易流水自动勾兑、对账结果看板', 'done', 1, '张伟', 'Xmu01', '2026-06-28 15:00:00', '2026-06-28 15:00:00'),
  ('XmD0122', 'SXm01', 'XmR012', 'XmD0120', 'V1.1 需求说明', '<h2>背景与目标</h2><p>差错处理：长短款工单与调账审批。</p><h2>需求范围</h2><ul><li><strong>差错工单自动生成</strong>：勾兑差异自动生成工单并指派</li><li><strong>调账审批流程</strong>：调账需双人复核，留存审计轨迹</li><li><strong>差错处理工作台</strong>：工单列表、详情与批量处理</li></ul><h2>验收标准</h2><ol><li>差错工单自动生成功能完整可用，异常场景有明确提示</li><li>调账审批流程功能完整可用，异常场景有明确提示</li><li>差错处理工作台功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-11-28 发布，发布前完成回归测试与上线评审。</p>', 'html', '差错处理：长短款工单与调账审批。范围：差错工单自动生成、调账审批流程、差错处理工作台', 'active', 2, '张伟', 'Xmu01', '2026-09-06 15:00:00', '2026-09-06 15:00:00'),
  ('XmD0123', 'SXm01', 'XmR012', 'XmD0120', 'V1.2 需求说明', '<h2>背景与目标</h2><p>商户自助：对账单订阅与下载中心。</p><h2>需求范围</h2><ul><li><strong>对账单邮件订阅</strong>：商户按日/月订阅对账单</li><li><strong>商户下载中心</strong>：历史对账单在线查询与下载</li></ul><h2>验收标准</h2><ol><li>对账单邮件订阅功能完整可用，异常场景有明确提示</li><li>商户下载中心功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2027-01-08 发布，发布前完成回归测试与上线评审。</p>', 'html', '商户自助：对账单订阅与下载中心。范围：对账单邮件订阅、商户下载中心', 'draft', 3, '张伟', 'Xmu01', '2026-11-23 15:00:00', '2026-11-23 15:00:00'),
