  ('XmD0131', 'SXm01', 'XmR013', 'XmD0130', 'V0.9 需求说明', '<h2>背景与目标</h2><p>内测版：规则引擎与黑白名单。</p><h2>需求范围</h2><ul><li><strong>实时规则引擎</strong>：基于 Drools 的规则编排与毫秒级决策</li><li><strong>黑白名单管理</strong>：设备、IP、卡号名单的增删与生效</li><li><strong>规则配置后台</strong>：规则可视化编辑、版本与灰度</li><li><strong>风控后台交互设计</strong>：规则编辑器与名单页交互</li></ul><h2>验收标准</h2><ol><li>实时规则引擎功能完整可用，异常场景有明确提示</li><li>黑白名单管理功能完整可用，异常场景有明确提示</li><li>规则配置后台功能完整可用，异常场景有明确提示</li><li>风控后台交互设计功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-12-10 发布，发布前完成回归测试与上线评审。</p>', 'html', '内测版：规则引擎与黑白名单。范围：实时规则引擎、黑白名单管理、规则配置后台、风控后台交互设计', 'active', 1, '张伟', 'Xmu01', '2026-09-13 15:00:00', '2026-09-13 15:00:00'),
  ('XmD0132', 'SXm01', 'XmR013', 'XmD0130', 'V1.0 需求说明', '<h2>背景与目标</h2><p>正式版：风险处置与案件管理。</p><h2>需求范围</h2><ul><li><strong>风险案件管理</strong>：命中高风险交易自动生成案件</li><li><strong>处置动作编排</strong>：拦截、延迟结算、人工审核等动作</li><li><strong>案件处理工作台</strong>：案件分派、处理与结案</li></ul><h2>验收标准</h2><ol><li>风险案件管理功能完整可用，异常场景有明确提示</li><li>处置动作编排功能完整可用，异常场景有明确提示</li><li>案件处理工作台功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2027-01-20 发布，发布前完成回归测试与上线评审。</p>', 'html', '正式版：风险处置与案件管理。范围：风险案件管理、处置动作编排、案件处理工作台', 'draft', 2, '张伟', 'Xmu01', '2026-12-06 15:00:00', '2026-12-06 15:00:00'),
