  ('XmD0213', 'SXm02', 'XmR021', 'XmD0210', 'V2.1 需求说明', '<h2>背景与目标</h2><p>付费会员：会员卡与自动续费。</p><h2>需求范围</h2><ul><li><strong>付费会员卡</strong>：月卡、季卡、年卡购买与生效</li><li><strong>自动续费签约</strong>：微信/支付宝代扣签约与续费</li><li><strong>会员卡购买页</strong>：卡种对比、购买与续费管理</li></ul><h2>验收标准</h2><ol><li>付费会员卡功能完整可用，异常场景有明确提示</li><li>自动续费签约功能完整可用，异常场景有明确提示</li><li>会员卡购买页功能完整可用，异常场景有明确提示</li><li>核心接口 P99 延迟不高于 300ms</li></ol><h2>上线计划</h2><p>计划 2026-11-14 发布，发布前完成回归测试与上线评审。</p>', 'html', '付费会员：会员卡与自动续费。范围：付费会员卡、自动续费签约、会员卡购买页', 'active', 3, '李婷', 'Xmu02', '2026-08-23 15:00:00', '2026-08-23 15:00:00'),
